UPDATE `quest_template` SET `QuestDescription`='Me brother tried draggin'' me off tae the Wetlands with some diggin'' crew out o'' Loch Modan. Said they were headin'' into hills no dwarf''s ever set boot in for some sort o'' excavation.\n\nAye, I''d ''ave gone, if I wasn''t already behind on this pile o'' girdles I''ve got to refit.\n\nDaewyn normally writes after he sends off, though. Haven''t heard a thing, gives me a strange feelin'' this time.\n\nIf yer marchin'' that way, mind checking in on me brother?', `LogDescription`='Look for Dorin Songblade''s brother, Daewyn, in Whelgar''s Excavation Site.', `AreaDescription`='', `QuestCompletionLog`='', `LogTitle`='Songblade Search', `QuestSortID`=16732, `QuestInfoID`=81, `SuggestedGroupNum`=0, `RewardNextQuest`=0, `RewardXPDifficulty`=6, `RewardXPMultiplier`=1.95, `RewardMoneyDifficulty`=0, `RewardMoneyMultiplier`=1.0, `RewardSpell`=0, `StartItem`=0, `Flags`=8, `FlagsEx`=0, `AllowableRaces`=18446744073709551615, `TimeAllowed`=0, `VerifiedBuild`=70862, `RewardItem1`=0, `RewardAmount1`=0, `ItemDrop1`=0, `ItemDropQuantity1`=0, `RewardItem2`=0, `RewardAmount2`=0, `ItemDrop2`=0, `ItemDropQuantity2`=0, `RewardItem3`=0, `RewardAmount3`=0, `ItemDrop3`=0, `ItemDropQuantity3`=0, `RewardItem4`=0, `RewardAmount4`=0, `ItemDrop4`=0, `ItemDropQuantity4`=0, `RewardChoiceItemID1`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemDisplayID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemDisplayID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemDisplayID3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemDisplayID4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity5`=0, `RewardChoiceItemDisplayID5`=0, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity6`=0, `RewardChoiceItemDisplayID6`=0, `RewardFactionID1`=0, `RewardFactionValue1`=0, `RewardFactionOverride1`=0, `RewardFactionCapIn1`=7, `RewardFactionID2`=0, `RewardFactionValue2`=0, `RewardFaction