-- B. Quest text in German (8 quests, a deDE cache of build 70790) and Russian (1 quest) where ours was missing or empty.
DELETE FROM `quest_template_locale` WHERE `ID`=86667 AND `locale`='deDE';
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`,`VerifiedBuild`) VALUES (86667,'deDE','Eingeschneit','Bringt einen Krug mit Schnee zu Norric Lochthane bei seinem Haus am nordwestlichen Ufer des Loch.','Mein alter Lehrmeister Norric hat mir einen kleinen Elementargeist geschickt und eine sonderbare Bitte ausrichten lassen: Norric braucht ein Glas Schnee für irgendein schamanisches Ritual! Ich habe keine Ahnung, was er damit vorhat, aber seine Methoden in Sachen Magie hinterfragt man besser nicht.\n\nIch bin zurzeit damit beschäftigt, die örtlichen Elementargeister kennenzulernen. Deshalb kann ich ihm leider nicht selbst helfen. Geht zum Tunneleingang am Südtorpass. Dort herrscht das ganze Jahr über Winter. Füllt diesen Krug mit Schnee und bringt ihn zu Norric, bevor er schmilzt. Der Krug sollte ihn kühl halten.','','','','','','',70790);
DELETE FROM `quest_template_locale` WHERE `ID`=96044 AND `locale`='deDE';
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`,`VerifiedBuild`) VALUES (96044,'deDE','Grundlagen des Zeltens: Schmiedekunst','Geht nach Kharanos und sprecht mit Tognus Flintfire, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.','Ah, Ihr habt Euch also dazu entschieden, $gSchmied:Schmiedin; zu werden. Eine sehr gute Wahl, denn so bleiben Eure Klingen immer scharf.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Schleifstein für Euer Lager bauen könnt. Wenn Ihr den Schleifstein aufstellt, stehen bald alle Krieger und Schurken aus der Gegend bei Euch Schlange, um ihre Waffen zu schärfen.','Suche nach dem Jägerlager','','','','','',70790);
DELETE FROM `quest_template_locale` WHERE `ID`=96046 AND `locale`='deDE';
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`,`VerifiedBuild`) VALUES (96046,'deDE','Grundlagen des Zeltens: Bergbau','Geht nach Kharanos und sprecht mit Yarr Hammerstone, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.','Bergbau ist zwar kein glamouröser Beruf, aber dafür ein ehrlicher.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Leitstein für Euer Lager herstellt. Mit einem Leitstein in Eurem Lager werden alle Leute, die gerne ein Schwert schwingen, sich um Eure Feuerstelle scharen, um den zusätzlichen Schub an Kampfkraft mitzunehmen.','Suche nach dem Jägerlager','','','','','',70790);
DELETE FROM `quest_template_locale` WHERE `ID`=96056 AND `locale`='deDE';
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`,`VerifiedBuild`) VALUES (96056,'deDE','Grundlagen des Zeltens: Kürschnerei','Geht nach Ironforge und sprecht mit Balthus Stoneflayer, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.','Die Kunst, erlegten Tieren Häute und Felle abzuziehen, ist eine der wertvollsten Fertigkeiten, die Ihr als $gAbenteurer:Abenteurerin; erlernen könnt.\n\nIch glaube, ich kenne da jemanden, der Euch zeigen kann, wie Ihr einen Lagerstuhl für Euer Lager anfertigt. Manchmal muss man sich einfach eine Pause gönnen, und aus den Fellen, die Ihr erbeutet habt, könnt Ihr Euch dafür einen gemütlichen Stuhl bauen. Ein wenig Entspannung kann Euch dabei helfen, immer in Eurer besten Form zu bleiben und bei Eurem nächsten Kampf genau an der richtigen Stelle zuzuschlagen.','Suche nach dem Jägerlager','','','','','',70790);
DELETE FROM `quest_template_locale` WHERE `ID`=96393 AND `locale`='deDE';
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`,`VerifiedBuild`) VALUES (96393,'deDE','Eindringlinge in der Altstadt von Ironforge','Betretet die Halle der Thanen unter der Altstadt von Ironforge und besorgt den Kopf von Durgen Dirgehammer.','Versammelt einige Verbündete und steigt in die Höhlen unter der Altstadt von Ironforge hinab. Betretet dort die Halle der Thanen und dringt bis zu den unteren Gewölben vor. \n\nMein Dunkeleisenzwergisch ist etwas eingerostet, aber ich kann einen Namen entziffern – Durgen Dirgehammer. Wahrscheinlich ist er der Kommandant. Schlagt seinen Kopf ab und bringt ihn zu König Magni Bronzebeard. \n\nOh, und richtet ihm aus, dass sein alter Freund Farsen ihn grüßen lässt!','','','','','','',70790);
DELETE FROM `quest_template_locale` WHERE `ID`=96629 AND `locale`='deDE';
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`,`VerifiedBuild`) VALUES (96629,'deDE','Grundlagen des Zeltens: Kochen','Sprecht mit Gremlock Pilsnor in Kharanos, um das Kochen zu erlernen.','Ihr möchtet also mehr über das Zelten erfahren, hm? Gute Idee, $C. Der erste Schritt in jedes Abenteuer besteht darin, kochen zu lernen und herauszufinden, wie man ein Lagerfeuer macht.\n\nBeim Kochen geht es nicht nur darum, leckeres Essen zuzubereiten. Es ist auch das Fundament, auf dem Ihr Euer Lager aufbaut.','Suche nach dem Jägerlager','','','','','',70790);
DELETE FROM `quest_template_locale` WHERE `ID`=97914 AND `locale`='deDE';
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`,`VerifiedBuild`) VALUES (97914,'deDE','Neue Horizonte','Bringt Thundris'' Brief zu Baros Alexston in Stormwind.\n\nThundris hat ein Schiff in Auberdine erwähnt, das Euch dorthin bringen kann.','Auberdine ist ein bescheidener Ort, $C. Ihr werdet seinen Namen nicht im Geäst von Darnassus hören. Die meisten erinnern sich nur an jene blühenden Städte, die die große Teilung uns genommen hat... Ameth''Aran, Bashal''Aran und... Lathar''Lazal.\n\nUnd doch bleibt Auberdine in ihrem Schatten.\n\nIch wünsche, dass unsere Arbeit hier Anerkennung findet. Ein neues Schiff verbindet uns mit dem Königreich Stormwind und bringt Leben und Vorräte an unsere Küsten. Ich bitte Euch, geht für die nächste Überfahrt an Bord und bringt diesen Brief zu einem Menschen namens Baros Alexston.\n\nVerbreitet die Kunde von unserer Heimat.','','','','','','',70790);
DELETE FROM `quest_template_locale` WHERE `ID`=98042 AND `locale`='deDE';
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`,`VerifiedBuild`) VALUES (98042,'deDE','Ein Blick in den Abgrund','Erbeutet ein unvergleichliches Auge von einem Jünger oder Schläger des Twilight-Hammers an der Meistergleve in Dunkelküste und findet in Auberdine jemanden, der bereit ist, es an sich zu nehmen.','<Als Ihr die einzelne Seite aus dem Twilight-Folianten reißt, erfüllt eine unheilvolle Stimme ungebeten Eure Gedanken.>\n\nSie sind gescheitert.\n\nIhr werdet der Vergessenheit anheimfallen.\n\nDas gewonnene Auge wird verloren gehen.','','','','','','',70790);
UPDATE `quest_template_locale` SET `LogTitle`=IF(COALESCE(`LogTitle`,'')='','Остановить заражение',`LogTitle`), `LogDescription`=IF(COALESCE(`LogDescription`,'')='','Убейте $1oa |4больного беженца:больных беженцев:больных беженцев; и $2oa |4изможденного беженца:изможденных беженцев:изможденных беженцев; по просьбе Далара Ткача Рассвета в Гробнице.',`LogDescription`), `QuestDescription`=IF(COALESCE(`QuestDescription`,'')='','Нам точно известно, что за появлением воргенов в Серебряном бору стоит Аругал. Возможно, он опять что-то задумал, а может, дело в чем-то еще. Чего мы не знаем, так это того, как распространяется проклятие.\n\nПока я ищу способ остановить его, нам срочно нужно предотвратить новое заражение. Похоже, Отрекшиеся неспособны подхватить эту хворь, но у Стены Седогрива собралась большая группа людей.\n\nСтупай туда и избавься от этих беженцев, пока они не стали прислужниками Аругала. И смотри, чтобы тебя не укусили, |3-6($r).',`QuestDescription`) WHERE `ID`=98299 AND `locale`='ruRU';

